class Solution {
public:
    int minSetBits(vector<int>& nums, int k) {
        const int B = 17;
        const int FULL = (1 << B) - 1;
        int n = nums.size();
        vector<int> cnt(B, 0);
        // initialise first window
        for (int i = 0; i < k; ++i) {
            int v = nums[i];
            for (int b = 0; b < B; ++b)
                if (v & (1 << b)) ++cnt[b];
        }
        auto curMask = [&]() -> int {
            int m = 0;
            for (int b = 0; b < B; ++b)
                if (cnt[b] == k) m |= (1 << b);
            return m;
        };
        int mask = curMask();
        if (mask == 0) return -1;
        vector<char> bad(1 << B, 0);
        bad[mask] = 1;
        // slide the window
        for (int i = k; i < n; ++i) {
            int out = nums[i - k];
            for (int b = 0; b < B; ++b)
                if (out & (1 << b)) --cnt[b];
            int in = nums[i];
            for (int b = 0; b < B; ++b)
                if (in & (1 << b)) ++cnt[b];
            mask = curMask();
            if (mask == 0) return -1;
            bad[mask] = 1;
        }
        // SOS DP: sub[mask] = true if any submask of mask appears as a window AND
        vector<char> sub = bad;
        for (int b = 0; b < B; ++b) {
            for (int m = 0; m < (1 << B); ++m) {
                if (m & (1 << b))
                    sub[m] |= sub[m ^ (1 << b)];
            }
        }
        int ans = INT_MAX;
        for (int y = 1; y <= FULL; ++y) {
            int comp = FULL ^ y;
            if (!sub[comp]) {
                int pc = __builtin_popcount(y);
                if (pc < ans) ans = pc;
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};
